## Empirical Benchmark Methodology

Below is a complete, reproducible C++ benchmark program. Compile with optimizations enabled (`-O3` on GCC/Clang).

```cpp
// benchmark_sort.cpp
// Compile: g++ -O3 -std=c++17 -march=native benchmark_sort.cpp -o benchmark_sort

#include <iostream>
#include <algorithm>
#include <chrono>
#include <random>
#include <vector>
#include <cmath>
#include <iomanip>
#include <numeric>

// ============================================================
// Custom QuickSort (naive implementation for comparison)
// ============================================================
void customQuickSort(std::vector<double>& arr, int low, int high) {
    if (low >= high) return;

    // Naive pivot: choose last element
    double pivot = arr[high];
    int i = low - 1;

    for (int j = low; j < high; ++j) {
        if (arr[j] <= pivot) {
            i++;
            std::swap(arr[i], arr[j]);
        }
    }
    std::swap(arr[i + 1], arr[high]);

    int partitionIndex = i + 1;
    customQuickSort(arr, low, partitionIndex - 1);
    customQuickSort(arr, partitionIndex + 1, high);
}

// Improved custom QuickSort with insertion sort cutoff and median-of-three
void insertionSort(std::vector<double>& arr, int left, int right) {
    for (int i = left + 1; i <= right; i++) {
        double key = arr[i];
        int j = i - 1;
        while (j >= left && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

double medianOfThree(std::vector<double>& arr, int low, int high) {
    int mid = low + (high - low) / 2;
    // Sort the three elements and pick the median
    if (arr[low] > arr[mid]) std::swap(arr[low], arr[mid]);
    if (arr[low] > arr[high]) std::swap(arr[low], arr[high]);
    if (arr[mid] > arr[high]) std::swap(arr[mid], arr[high]);
    // Now arr[low] <= arr[mid] <= arr[high]
    // Place median at arr[high - 1] for clean partitioning
    std::swap(arr[mid], arr[high - 1]);
    return arr[high - 1];
}

void improvedQuickSort(std::vector<double>& arr, int low, int high) {
    const int INSERTION_THRESHOLD = 16;

    while (high - low > INSERTION_THRESHOLD) {
        double pivot = medianOfThree(arr, low, high);
        int i = low;
        int j = high - 1;

        while (true) {
            while (arr[++i] < pivot) {}
            while (arr[--j] > pivot) {}
            if (i < j) {
                std::swap(arr[i], arr[j]);
            } else {
                break;
            }
        }
        std::swap(arr[i], arr[high - 1]);

        // Recurse on the smaller partition first (reduces stack depth)
        if (i - low < high - i) {
            improvedQuickSort(arr, low, i - 1);
            low = i + 1;
        } else {
            improvedQuickSort(arr, i + 1, high);
            high = i - 1;
        }
    }

    // Finish with insertion sort
    if (low < high) {
        insertionSort(arr, low, high);
    }
}

// ============================================================
// Benchmark infrastructure
// ============================================================
template<typename SortFunc>
double benchmarkTime(int N, SortFunc sorter, const std::string& which) {
    // Generate fresh random data for each run to avoid cache effects from previous sorts
    std::mt19937_64 rng(42); // Fixed seed for reproducibility
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    std::vector<double> data(N);
    for (int i = 0; i < N; i++) {
        data[i] = dist(rng);
    }

    auto start = std::chrono::high_resolution_clock::now();
    sorter(data);
    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
    double seconds = duration / 1e6;

    std::cout << which << ": " << std::fixed << std::setprecision(4) << seconds << " seconds";

    // Verify correctness
    bool sorted = std::is_sorted(data.begin(), data.end());
    std::cout << " | Sorted: " << (sorted ? "YES" : "NO") << std::endl;

    if (!sorted) {
        std::cerr << "ERROR: Sort produced incorrect result!" << std::endl;
    }

    return seconds;
}

int main() {
    const int N = 10'000'000;
    const int TRIALS = 5;

    std::cout << "=== Sorting " << N << " doubles uniformly distributed on [0,1) ===" << std::endl;
    std::cout << std::endl;

    // --- std::sort ---
    std::cout << "--- std::sort ---" << std::endl;
    double sumStdSort = 0;
    for (int t = 0; t < TRIALS; t++) {
        double time = benchmarkTime(N,
            [] (std::vector<double>& vec) {
                std::sort(vec.begin(), vec.end());
            },
            std::string("  Trial ") + std::to_string(t + 1)
        );
        sumStdSort += time;
    }
    double avgStdSort = sumStdSort / TRIALS;

    std::cout << std::endl;

    // --- Naive custom QuickSort ---
    std::cout << "--- Naive Custom QuickSort ---" << std::endl;
    double naiveSum = 0;
    for (int t = 0; t < TRIALS; t++) {
        // Re-seed to get same distribution but fresh vector
        double time = benchmarkTime(N,
            [] (std::vector<double>& vec) {
                customQuickSort(vec, 0, static_cast<int>(vec.size()) - 1);
            },
            std::string("  Trial ") + std::to_string(t + 1)
        );
        // The vector is destroyed after each trial, so we need to regenerate.
        // benchmarkTime generates its own data, so this is fine.
        naiveSum += time;
